/*
 * Minimal diagnostic host for the official 32-bit KMSCNAPI.dll.
 *
 * This program does not contain or redistribute the vendor library. It loads
 * a caller-selected DLL, performs one read-only get_service_information call,
 * and prints the returned status. Point the URL at a local capture server to
 * inspect the exact request generated by the official implementation.
 */

#include <stdio.h>
#include <stdlib.h>
#include <windows.h>

typedef void *(__cdecl *kmscn_init_fn)(const char *url);
typedef int (__cdecl *kmscn_get_service_information_fn)(void *context, void *output);
typedef int (__cdecl *kmscn_get_capability_fn)(void *context, void *output);
typedef int (__cdecl *kmscn_open_session_fn)(void *context, void *input);
typedef int (__cdecl *kmscn_start_scan_fn)(void *context, void *input);
typedef int (__cdecl *kmscn_retrieve_image_fn)(void *context, void **data, unsigned int *length);
typedef int (__cdecl *kmscn_close_session_fn)(void *context);
typedef void (__cdecl *kmscn_exit_fn)(void *context);

int main(int argc, char **argv)
{
    HMODULE library;
    kmscn_init_fn init;
    kmscn_get_service_information_fn get_service_information;
    kmscn_get_capability_fn get_capability;
    kmscn_open_session_fn open_session;
    kmscn_start_scan_fn start_scan;
    kmscn_retrieve_image_fn retrieve_image;
    kmscn_close_session_fn close_session;
    kmscn_exit_fn exit_scan;
    unsigned char *output;
    void *context;
    const char *operation;
    int result;

    if (argc < 3 || argc > 4) {
        fprintf(stderr,
                "usage: %s <KMSCNAPI.dll> <base-url> "
                "[service-info|capability|open-session|open-session-empty|"
                "start-scan|scan-sequence]\n",
                argv[0]);
        return 2;
    }
    operation = argc == 4 ? argv[3] : "service-info";

    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
    library = LoadLibraryA(argv[1]);
    if (library == NULL) {
        fprintf(stderr, "LoadLibrary failed: %lu\n", GetLastError());
        return 2;
    }

    init = (kmscn_init_fn)GetProcAddress(library, "KMSCNInit");
    get_service_information =
        (kmscn_get_service_information_fn)GetProcAddress(library, "KMSCNGetServiceInfo");
    get_capability =
        (kmscn_get_capability_fn)GetProcAddress(library, "KMSCNGetCapability");
    open_session =
        (kmscn_open_session_fn)GetProcAddress(library, "KMSCNOpenSession");
    start_scan =
        (kmscn_start_scan_fn)GetProcAddress(library, "KMSCNStartScan");
    retrieve_image =
        (kmscn_retrieve_image_fn)GetProcAddress(library, "KMSCNRetrieveImage");
    close_session =
        (kmscn_close_session_fn)GetProcAddress(library, "KMSCNCloseSession");
    exit_scan = (kmscn_exit_fn)GetProcAddress(library, "KMSCNExit");
    if (init == NULL || get_service_information == NULL || get_capability == NULL
        || open_session == NULL || start_scan == NULL || retrieve_image == NULL
        || close_session == NULL || exit_scan == NULL) {
        fprintf(stderr, "required KMSCNAPI exports are missing\n");
        FreeLibrary(library);
        return 2;
    }

    context = init(argv[2]);
    if (context == NULL) {
        fprintf(stderr, "KMSCNInit returned NULL\n");
        FreeLibrary(library);
        return 2;
    }

    output = (unsigned char *)calloc(1, 65536);
    if (output == NULL) {
        fprintf(stderr, "output allocation failed\n");
        exit_scan(context);
        FreeLibrary(library);
        return 2;
    }

    if (strcmp(operation, "service-info") == 0) {
        result = get_service_information(context, output);
        printf("KMSCNGetServiceInfo=%d\n", result);
    } else if (strcmp(operation, "capability") == 0) {
        result = get_capability(context, output);
        printf("KMSCNGetCapability=%d\n", result);
    } else if (strcmp(operation, "open-session") == 0
               || strcmp(operation, "open-session-empty") == 0
               || strcmp(operation, "scan-sequence") == 0) {
        /* twOpenSessionReqInit shape recovered from KMNETSCN3.dll. */
        const char *host_data =
            strcmp(operation, "open-session-empty") == 0 ? "" : "127.0.0.2";
        ((unsigned int *)output)[0] = host_data[0] == '\0' ? -1 : 0;
        ((const char **)output)[1] = host_data;
        ((unsigned int *)output)[2] = 0;
        ((unsigned int *)output)[3] = 0;
        ((int *)output)[4] = -1;
        result = open_session(context, output);
        printf("KMSCNOpenSession=%d\n", result);
        if (result == 0 && strcmp(operation, "scan-sequence") == 0) {
            memset(output, 0, 65536);
            /* Default scan configuration is filled by KMSCNAPI serialization. */
            result = start_scan(context, output);
            printf("KMSCNStartScan=%d\n", result);
            if (result == 0) {
                void *image_data = NULL;
                unsigned int image_length = 0;
                result = retrieve_image(
                    context,
                    &image_data,
                    &image_length
                );
                printf(
                    "KMSCNRetrieveImage=%d length=%u data=%p\n",
                    result,
                    image_length,
                    image_data
                );
            }
            memset(output, 0, 65536);
            result = close_session(context);
            printf("KMSCNCloseSession=%d\n", result);
        }
    } else if (strcmp(operation, "start-scan") == 0) {
        memset(output, 0, 65536);
        result = start_scan(context, output);
        printf("KMSCNStartScan=%d\n", result);
    } else {
        fprintf(stderr, "unknown operation: %s\n", operation);
        result = 2;
    }

    free(output);
    exit_scan(context);
    FreeLibrary(library);
    return result == 0 ? 0 : 1;
}
